import{_ as a,o as e,c as n,a3 as l}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"周易","description":"五经之「易」，群经之首——本站易经板块的入口指引。","frontmatter":{"title":"周易","description":"五经之「易」，群经之首——本站易经板块的入口指引。","category":"guide","aliases":["周易","易经","五经之易","zhouyi"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/yijing.md","filePath":"lizhimingde/sishu-wujing/yijing.md","lastUpdated":1789987057000}'),r={name:"lizhimingde/sishu-wujing/yijing.md"};function t(o,i,s,h,g,u){return e(),n("div",null,[...i[0]||(i[0]=[l('<h1 id="周易" tabindex="-1">周易 <a class="header-anchor" href="#周易" aria-label="Permalink to &quot;周易&quot;">​</a></h1><p>《周易》居<strong>五经之首</strong>。不过本站的易经内容已另有完整板块，<strong>这里只作入口指引，不重复建设</strong>——本页告诉你「易为什么排在首位」，以及正文该往哪里读。</p><h2 id="为什么「易」为五经之首" tabindex="-1">为什么「易」为五经之首 <a class="header-anchor" href="#为什么「易」为五经之首" aria-label="Permalink to &quot;为什么「易」为五经之首&quot;">​</a></h2><ul><li><strong>它是群经的源头</strong>：六十四卦与《易传》（十翼）提供了一套贯通天地人的符号与义理系统，儒家与道家都从这里取资源。</li><li><strong>孔子晚年好《易》</strong>：「加我数年，五十以学《易》，可以无大过矣」——儒门把它列为必修。</li><li><strong>它既是占筮之书，也是义理之书</strong>：从卜辞到「穷则变，变则通，通则久」的哲学，它完成了中国文化里最早的「由术入道」。</li><li><strong>四书五经的其余各部，多多少少在与「易」的世界观对话</strong>——《中庸》讲天道、《礼记·月令》讲时令、《春秋》讲次异与人事，背后都有「易」的影子。</li></ul><h2 id="去哪读-本站易经板块" tabindex="-1">去哪读（本站易经板块） <a class="header-anchor" href="#去哪读-本站易经板块" aria-label="Permalink to &quot;去哪读（本站易经板块）&quot;">​</a></h2><ul><li><a href="/Dao/yijing/"><strong>易经板块总览</strong></a>——从这里进入</li><li><a href="/Dao/yijing/hexagrams/">六十四卦目录</a>——按卦序排列的六十四卦页</li><li><a href="/Dao/yijing/shi-yi/">十翼导读</a>——彖、象、系辞、文言、序卦、杂卦等</li><li><a href="/Dao/yijing/basics/core-concepts">基础概念</a>——阴阳、爻位、卦象等入门概念</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>四书五经栏目里的「易」，<strong>不另建一套</strong>：正文阅读一律指向 <code>/yijing/</code>。</li><li>这样做是为了避免同一份经典在两处并行维护、日久漂移。</li><li>若将来需要「以四书五经的视角读易」（比如专讲易与《中庸》《春秋》的关系），会作为<strong>专题</strong>另立，而不是复制原典。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/shijing/">诗经</a> · <a href="/Dao/lizhimingde/sishu-wujing/shangshu/">尚书</a> · <a href="/Dao/lizhimingde/sishu-wujing/liji/">礼记</a> · <a href="/Dao/lizhimingde/sishu-wujing/chunqiu/">春秋</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',10)])])}const m=a(r,[["render",t]]);export{c as __pageData,m as default};
